select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('HeyGen Video Agent', 'Synthesia (Syren video agent)', 'ElevenAgents', 'Vapi', 'Retell AI', 'Bland', 'Grammarly (AI agents)', 'Descript Underlord', 'Microsoft 365 Copilot (Researcher & Analyst agents)', 'Attio (Ask Attio & AI agents)', 'Avoma', 'CrewAI', 'Warp', 'Base44', 'Sintra AI') order by e.name;
